import math

def geometric_mean(numbers: list[float]) -> float:
    """
    Calculates the geometric mean of a list of positive numbers.

    Args:
        numbers: A list of positive floating-point numbers.

    Returns:
        The geometric mean as a float.

    Raises:
        ValueError: If the input list is empty or contains non-positive numbers.
    """
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    product: float = 1.0
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers must be positive for geometric mean.")
        product *= num

    n: int = len(numbers)
    return product**(1/n)

def _is_positive_number(num: float) -> bool:
    """Helper function to check if a number is positive."""
    return num > 0

def _calculate_product(data: list[float]) -> float:
    """Helper function to calculate the product of numbers in a list."""
    current_product: float = 1.0
    for x in data:
        current_product *= x
    return current_product

def _get_nth_root(base: float, n: int) -> float:
    """Helper function to calculate the nth root."""
    return base**(1/n)

