def encrypt_shift(text: str, shift: int) -> str:
    """
    Encrypts a string using a simple shift cipher.
    """
    result: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted_char: str = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            result.append(shifted_char)
        elif 'A' <= char <= 'Z':
            shifted_char: str = chr(((ord(char) - ord('A') + shift) % 26) + ord('A'))
            result.append(shifted_char)
        else:
            result.append(char)
    return "".join(result)

