def convert_temperature(value: float, unit_from: str, unit_to: str) -> float:
    """Converts temperature between Celsius, Fahrenheit, and Kelvin."""

    if unit_from == unit_to:
        return value

    # Convert to Kelvin first
    if unit_from == 'C':
        kelvin_value: float = value + 273.15
    elif unit_from == 'F':
        kelvin_value = (value - 32) * 5/9 + 273.15
    else:  # unit_from == 'K'
        kelvin_value = value

    # Convert from Kelvin to target unit
    if unit_to == 'C':
        result: float = kelvin_value - 273.15
    elif unit_to == 'F':
        result = (kelvin_value - 273.15) * 9/5 + 32
    else:  # unit_to == 'K'
        result = kelvin_value

    return result

